#!/usr/bin/env bash
# Stage 6 acceptance gate. Exits non-zero on the FIRST failing check (set -e).
# Do not edit this file, tools/check-boundaries.*, or the seeded-defect
# catalog to force a pass — the gate must stay honest.
set -euo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")"

# Load OPENROUTER_API_KEY etc. from .env if present (never committed).
if [ -f .env ]; then
  set -a
  # shellcheck disable=SC1091
  source .env
  set +a
fi

export MAX_FALSE_POSITIVE_RATE="${MAX_FALSE_POSITIVE_RATE:-0}"
# Stage 6b thresholds — deliberate, committed, visible (same pattern as
# MAX_FALSE_POSITIVE_RATE above). Set below the measured values at authoring
# time (catch rate 90% over 10 real defects; triage accuracy 100% over a
# 12-case labelled battery — see VERIFICATION.md Stage 6b) to leave headroom
# for LLM nondeterminism while still catching a real regression.
export MIN_CATCH_RATE="${MIN_CATCH_RATE:-0.8}"
export MIN_TRIAGE_ACCURACY="${MIN_TRIAGE_ACCURACY:-0.8}"

# The gate runs in its OWN throwaway tests directory so it never clobbers the
# durable regression suite in generated-tests/ (built via run-workflow --all or
# ops/sync-requirements --apply). Honored by run-workflow.js, run-eval.js, and
# run-triage-battery.js (see workflow/tests-dir.js).
export GENERATED_TESTS_DIR="${GENERATED_TESTS_DIR:-generated-tests-gate}"

# Deliberate, visible scope for the gate's clean run + eval (not the full
# --all sweep across all 44 cypress-rwa requirements): these 4 requirements
# are the ones with curated, field-level apiHints (see
# adapters/cypress-rwa/workflow-adapter.js CURATED_API_HINTS) needed for
# reliable, ungrounded-invention-free test generation, and together they
# cover all 3 seeded-defect targets plus 2+ traceability spot-checks. This
# keeps the gate fast and deterministic; `npm run workflow -- --all` still
# exercises the full requirement set on demand. See VERIFICATION.md.
GATE_REQUIREMENTS=(
  "CYPRESS-RWA-TRANSACTIONS-007"
  "CYPRESS-RWA-USERS-001"
  "CYPRESS-RWA-TRANSACTIONS-001"
  "CYPRESS-RWA-BANK-ACCOUNTS-001"
)

step() { printf '\n=== %s ===\n' "$1"; }

step "1/8 check:boundaries"
npm run check:boundaries

step "2/8 workflow unit tests"
node --test

step "3/8 stage-5 container smoke check"
# API-only scope (docs/build-prompts/stage6-build-prompt.md) — only the backend (3001) needs to
# be reachable from the host. The frontend (Vite, 3000) binds to loopback
# inside the container and is intentionally not part of this check; see
# VERIFICATION.md.
./docker/run.sh start
for i in $(seq 1 60); do
  if curl -sf http://localhost:3001/testData/users >/dev/null 2>&1; then
    echo "app reachable (api:3001)"
    break
  fi
  if [ "$i" -eq 60 ]; then
    echo "FAIL: app did not become reachable" >&2
    exit 1
  fi
  sleep 1
done

step "4/8 clean run (generate -> N-run+reset -> triage -> report)"
rm -rf reports "$GENERATED_TESTS_DIR"
REQ_ARGS=()
for id in "${GATE_REQUIREMENTS[@]}"; do
  REQ_ARGS+=(--requirement "$id")
done
node run-workflow.js "${REQ_ARGS[@]}" --out reports --tests-dir "$GENERATED_TESTS_DIR"

node -e "
const sc = JSON.parse(require('fs').readFileSync('reports/scorecard.json', 'utf8'));
const max = Number(process.env.MAX_FALSE_POSITIVE_RATE);
if (!Number.isFinite(max)) { console.error('FAIL: MAX_FALSE_POSITIVE_RATE is not a number:', process.env.MAX_FALSE_POSITIVE_RATE); process.exit(1); }
console.log('false-positive rate:', sc.falsePositiveRate, '(threshold <=', max + ')');
console.log('quarantined (flaky, excluded from scoring):', sc.tests.quarantinedFlaky);
console.log('orphan test ids:', JSON.stringify(sc.traceability.orphanTestIds));
if (sc.falsePositiveRate > max) {
  console.error('FAIL: false-positive rate', sc.falsePositiveRate, 'exceeds MAX_FALSE_POSITIVE_RATE', max);
  process.exit(1);
}
if (sc.traceability.orphanTestIds.length > 0) {
  console.error('FAIL: orphan test ids found (no valid requirementId):', sc.traceability.orphanTestIds);
  process.exit(1);
}
"

step "5/8 seeded-defect eval (catch rate, expanded catalog incl. negative controls)"
node eval/run-eval.js

node -e "
const sc = JSON.parse(require('fs').readFileSync('reports/scorecard.json', 'utf8'));
const min = Number(process.env.MIN_CATCH_RATE);
if (!Number.isFinite(min)) { console.error('FAIL: MIN_CATCH_RATE is not a number:', process.env.MIN_CATCH_RATE); process.exit(1); }
console.log('catch rate (real defects only):', sc.catchRate, '(threshold >=', min + ')');
console.log('negative controls correctly uncaught:', sc.negativeControls.correctlyUncaught + '/' + sc.negativeControls.total,
  sc.negativeControls.unexpectedlyCaught.length ? '(unexpectedly caught: ' + sc.negativeControls.unexpectedlyCaught.join(', ') + ')' : '');
console.log('unmeasured test ids (no targeting real defect):', JSON.stringify(sc.unmeasuredTestIds));
// A missed real defect (expectCaught !== false) is the only failure here.
// An uncaught negative control is the EXPECTED, correct outcome — never a
// failure; an unexpectedly-caught one is reported above but also not a
// failure (it means detection is better than assumed).
const missed = sc.defects.filter(d => d.expectCaught !== false && !d.caught);
if (missed.length > 0) {
  console.error('FAIL: missed real defects:', missed.map(d => d.id));
  process.exit(1);
}
if (sc.catchRate < min) {
  console.error('FAIL: catch rate', sc.catchRate, 'is below MIN_CATCH_RATE', min);
  process.exit(1);
}
"

step "6/8 triage stress-test battery (confusion matrix, accuracy)"
node eval/run-triage-battery.js

node -e "
const b = JSON.parse(require('fs').readFileSync('reports/triage-battery.json', 'utf8'));
const min = Number(process.env.MIN_TRIAGE_ACCURACY);
if (!Number.isFinite(min)) { console.error('FAIL: MIN_TRIAGE_ACCURACY is not a number:', process.env.MIN_TRIAGE_ACCURACY); process.exit(1); }
console.log('triage accuracy:', b.accuracy, '(' + b.correct + '/' + b.scored + ', threshold >=', min + ')');
console.log('confusion matrix:', JSON.stringify(b.matrix));
if (b.misclassifiedIds.length > 0) console.log('misclassified:', JSON.stringify(b.misclassifiedIds));
if (b.accuracy < min) {
  console.error('FAIL: triage accuracy', b.accuracy, 'is below MIN_TRIAGE_ACCURACY', min);
  process.exit(1);
}
"

step "7/8 uncurated --all breadth snapshot (reported, no threshold — see VERIFICATION.md Stage 6b workstream C)"
# This reads a committed snapshot captured by a one-off, deliberately
# out-of-band run of 'node run-workflow.js --all --out reports-all' against
# the live LLM (see VERIFICATION.md) — NOT re-run on every gate invocation.
# Re-running the full uncurated 44-requirement sweep live on every gate
# execution would make the standing gate slow, costly, and noisy (the exact
# tradeoff the original 4-requirement scope decision in VERIFICATION.md
# Stage 6 §3 already called out); refresh reports-all/ manually and re-copy
# the snapshot when intentionally re-measuring breadth.
if [ -f reports-all/scorecard.json ]; then
  node -e "
  const sc = JSON.parse(require('fs').readFileSync('reports-all/scorecard.json', 'utf8'));
  console.log('requirements covered:', sc.requirements.covered + '/' + sc.requirements.total);
  console.log('tests generated:', sc.tests.generated, '| passed:', sc.tests.passed, '| failed:', sc.tests.failed, '| quarantined:', sc.tests.quarantinedFlaky);
  console.log('uncurated false-positive rate:', sc.falsePositiveRate, '(reported only, no gate threshold)');
  "
else
  echo "no reports-all/scorecard.json snapshot present — see VERIFICATION.md Stage 6b workstream C for how to regenerate it"
fi

step "8/8 done"
echo "All Stage 6 gate checks passed."
